        if (typeof obj !== 'object' || obj === null) {
            throw new Error("Expected an object as input");
        }

        // Check if there's no more keys left to traverse or the current key does not exist.
        if (i === keys.length - 1 && !hasOwnProperty(obj, keys[i])) {
            break;
        }

        obj = obj[keys[i]];
    }

    return obj;
}

